R,C=23,25
a=[[0]*C for _ in range(R)]
rects=[(0,3,9,11),(1,4,19,22),(3,5,4,6),(3,7,13,17),(6,8,22,23),(9,11,9,10),(10,13,1,5),(16,20,5,13),(16,18,21,23),(18,19,17,18)]
for r1,r2,c1,c2 in rects:
 for r in range(r1,r2+1):
  for c in range(c1,c2+1): a[r][c]=2
# recolor any 4-connected component of 2 intersecting one of the axis lines
seen=set()
for r in range(R):
 for c in range(C):
  if a[r][c]!=2 or (r,c) in seen: continue
  comp=[]; stack=[(r,c)]; seen.add((r,c))
  while stack:
   x,y=stack.pop(); comp.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    p,q=x+dx,y+dy
    if 0<=p<R and 0<=q<C and a[p][q]==2 and (p,q) not in seen:
     seen.add((p,q)); stack.append((p,q))
  if any(x in (4,11) or y==5 for x,y in comp):
   for x,y in comp:a[x][y]=1
for c in range(C):a[4][c]=a[11][c]=1
for r in range(R):a[r][5]=1
import json
print('dims',len(a),set(map(len,a)))
